import java.util.*;

class Solution {
  public Node findRoot(List<Node> tree) {
    // every value appears once as a node, and once more as a child unless it is the root
    long sum = 0;
    for (Node n : tree) {
      sum += n.val;
      for (Node c : n.children) sum -= c.val;
    }
    for (Node n : tree) if (n.val == sum) return n;
    return null;
  }
}
